def strong_password_checker(password: str) -> int:
    """
    Calculate the minimum number of steps (insert, delete, replace) to make password strong:
    1. Length between 6 and 20.
    2. At least 1 lowercase, 1 uppercase, 1 digit.
    3. No three consecutive identical characters.
    """
    n = len(password)

    has_lower = any(c.islower() for c in password)
    has_upper = any(c.isupper() for c in password)
    has_digit = any(c.isdigit() for c in password)
    missing_types = (not has_lower) + (not has_upper) + (not has_digit)

    # Find consecutive repeating character sequence lengths >= 3
    runs = []
    i = 0
    while i < n:
        j = i
        while j < n and password[j] == password[i]:
            j += 1
        length = j - i
        if length >= 3:
            runs.append(length)
        i = j

    if n < 6:
        return max(6 - n, missing_types)
    elif n <= 20:
        replace_count = sum(length // 3 for length in runs)
        return max(replace_count, missing_types)
    else:
        deletions = n - 20
        replace_count = sum(length // 3 for length in runs)

        # Prioritize deletions to reduce replacement count efficiently:
        # Step 1: Runs where length % 3 == 0 (1 deletion saves 1 replacement)
        d = deletions
        for idx in range(len(runs)):
            if d >= 1 and runs[idx] % 3 == 0:
                d -= 1
                replace_count -= 1
                runs[idx] -= 1

        # Step 2: Runs where length % 3 == 1 (2 deletions save 1 replacement)
        for idx in range(len(runs)):
            if d >= 2 and runs[idx] % 3 == 1:
                d -= 2
                replace_count -= 1
                runs[idx] -= 2

        # Step 3: Remaining deletions (3 deletions save 1 replacement)
        if d > 0 and replace_count > 0:
            replace_count -= d // 3
            if replace_count < 0:
                replace_count = 0

        return deletions + max(replace_count, missing_types)

import heapq
from collections import defaultdict


def median_sliding_window(nums: list[int], k: int) -> list[float]:
    """
    Return double-precision floating point medians for each sliding window of size k.
    Runs in strict O(N log K) time using dual heaps with lazy deletion.
    """
    if not nums or k <= 0:
        return []

    small = []  # Max-heap (storing negated values for smaller half)
    large = []  # Min-heap (storing values for larger half)
    delayed = defaultdict(int)

    small_size = 0
    large_size = 0
    target_diff = 1 if k % 2 == 1 else 0

    def prune_small() -> None:
        while small and delayed[-small[0]] > 0:
            delayed[-small[0]] -= 1
            heapq.heappop(small)

    def prune_large() -> None:
        while large and delayed[large[0]] > 0:
            delayed[large[0]] -= 1
            heapq.heappop(large)

    def rebalance() -> None:
        nonlocal small_size, large_size
        while small_size > large_size + target_diff:
            prune_small()
            val = -heapq.heappop(small)
            heapq.heappush(large, val)
            small_size -= 1
            large_size += 1

        while small_size < large_size + target_diff:
            prune_large()
            val = heapq.heappop(large)
            heapq.heappush(small, -val)
            large_size -= 1
            small_size += 1

        prune_small()
        prune_large()

    def add_num(x: int) -> None:
        nonlocal small_size, large_size
        prune_small()
        if small and x <= -small[0]:
            heapq.heappush(small, -x)
            small_size += 1
        else:
            heapq.heappush(large, x)
            large_size += 1
        rebalance()

    def remove_num(x: int) -> None:
        nonlocal small_size, large_size
        prune_small()
        prune_large()
        if small and x <= -small[0]:
            small_size -= 1
            if x == -small[0]:
                heapq.heappop(small)
            else:
                delayed[x] += 1
        else:
            large_size -= 1
            if large and x == large[0]:
                heapq.heappop(large)
            else:
                delayed[x] += 1
        rebalance()

    def get_median() -> float:
        prune_small()
        prune_large()
        if k % 2 == 1:
            return float(-small[0])
        else:
            return (-small[0] + large[0]) / 2.0

    res = []
    for i, num in enumerate(nums):
        add_num(num)
        if i >= k - 1:
            res.append(get_median())
            remove_num(nums[i - k + 1])

    return res

def is_match(s: str, p: str) -> bool:
    """
    Given an input string s and a pattern p, implement regular expression matching with support for '.' and '*' where:
    - '.' Matches any single character.
    - '*' Matches zero or more of the preceding element.
    The matching should cover the entire input string (not partial).
    """
    m, n = len(s), len(p)
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = True

    for j in range(2, n + 1):
        if p[j - 1] == '*':
            dp[0][j] = dp[0][j - 2]

    for i in range(1, m + 1):
        s_char = s[i - 1]
        for j in range(1, n + 1):
            p_char = p[j - 1]
            if p_char == '*':
                prev_p_char = p[j - 2]
                dp[i][j] = dp[i][j - 2] or (
                    (prev_p_char == '.' or prev_p_char == s_char) and dp[i - 1][j]
                )
            else:
                dp[i][j] = (p_char == '.' or p_char == s_char) and dp[i - 1][j - 1]

    return dp[m][n]
